declare(strict_types=1);require_once __DIR__.'/admin_settings.php';require_once __DIR__.'/asaas.php';$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';if(!preg_match('~^/j/([A-Za-z0-9_-]{6,40})$~',$path,$m)){http_response_code(404);exit('QR invalido');}$token=$m[1];$q=settings_db()->prepare("SELECT vt.label,v.name venueName,v.logoPath,v.musicPriceCents,v.dedicationPriceCents FROM venueTables vt JOIN venues v ON v.id=vt.venueId WHERE vt.qrToken=? AND vt.status='ACTIVE' LIMIT 1");$q->execute([$token]);$t=$q->fetch();if(!$t){http_response_code(404);exit('QR nao encontrado');}$name=htmlspecialchars((string)$t['venueName'],ENT_QUOTES,'UTF-8');$barLogo=(string)($t['logoPath']??'');if(!preg_match('#^/assets/logos/[A-Za-z0-9_.-]+$#',$barLogo))$barLogo='/assets/tocaraul_logo.png';$label='Pedidos do bar';$music=(int)$t['musicPriceCents'];$ded=(int)$t['dedicationPriceCents'];$ready=asaas_ready();function h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}header('Content-Type:text/html;charset=utf-8');?>
<!doctype html><html lang=pt-BR><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title><?=$name?> · TocaRaul</title><style>*{box-sizing:border-box}body{margin:0;background:#090909;color:#fff;font-family:system-ui;font-size:19px}.wrap{max-width:720px;margin:auto;padding:20px 16px 100px}.topbar{display:flex;align-items:center;justify-content:center;margin-bottom:4px}.logo{display:flex;align-items:center;gap:12px}.logo img{height:92px;width:92px;object-fit:contain;filter:drop-shadow(0 2px 14px rgba(255,204,0,.35))}.logo span{font-size:44px;font-weight:900;color:#ffcc00;letter-spacing:.5px}.tablechip{text-align:center;margin-bottom:6px}.chip{display:inline-block;background:#171717;border:1px solid #333;border-radius:999px;padding:10px 16px;font-size:18px;font-weight:700}.hero{margin:22px 0}.hero h1{font-size:38px;margin:0;line-height:1.1}.hero p{font-size:20px}
.steps{display:flex;gap:8px;margin:18px 0}.step-dot{flex:1;text-align:center;padding:10px 4px;border-radius:10px;background:#171717;color:#666;font-size:14px;font-weight:800}.step-dot.active{background:#241d04;color:#ffcc00;border:1px solid #ffcc00}.step-dot.done{color:#9dffa9}
.stepview{display:none}.stepview.on{display:block}
.grid{display:grid;gap:10px}.song,.card{background:#121212;border:1px solid #292929;border-radius:18px;padding:18px}.song{color:#fff;text-align:left;width:100%;min-width:0;display:flex;align-items:center;gap:12px;font-size:19px;padding:12px;cursor:pointer}.song.selected{border-color:#ffcc00;border-width:2px}.song span{color:#999;font-size:17px}.song b{color:#ffcc00;font-size:20px;flex-shrink:0}.song img{width:64px;height:64px;border-radius:10px;object-fit:cover;flex-shrink:0;background:#070707}.song .info{flex:1;min-width:0}.song .info strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.song .info span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.preview{width:38px;height:38px;border-radius:50%;background:#000;border:1px solid #444;color:#ffcc00;font-size:15px;flex-shrink:0;display:flex;align-items:center;justify-content:center;padding:0}
#previewBox{display:none}.preview{display:none!important}.song:after{content:'Escolher';background:#c94a40;color:#fff;border-radius:5px;padding:8px 10px;font-size:14px;font-weight:800;white-space:nowrap}
.chosen{display:flex;align-items:center;gap:12px;margin-bottom:16px;background:#0c0c0c;border:1px solid #292929;border-radius:14px;padding:12px}.chosen img{width:56px;height:56px;border-radius:10px;object-fit:cover;flex-shrink:0}.chosen .info{flex:1;min-width:0}.chosen .info strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.chosen .info span{color:#999;font-size:16px}
.card h2{font-size:24px}.field{margin-top:14px}.field label{display:block;color:#ccc;font-size:16px;margin-bottom:6px}input,textarea{width:100%;background:#070707;color:#fff;border:1px solid #333;border-radius:12px;padding:15px;font-size:19px}textarea{min-height:80px}.total{display:flex;justify-content:space-between;font-size:26px;font-weight:900;margin-top:15px}.btn{width:100%;border:0;border-radius:13px;background:#ffcc00;color:#090909;padding:18px;font-weight:900;margin-top:15px;font-size:21px}.btn:disabled{opacity:.4}.btn.ghost{background:#222;color:#ffcc00;border:1px dashed #ffcc00}
.pixbadge{display:flex;align-items:center;gap:14px;background:#0d1f1d;border:1px solid #1f4a45;border-radius:14px;padding:14px;margin-bottom:14px}.pixlogo{background:#fff;border-radius:8px;padding:8px 10px;flex-shrink:0;line-height:0}.pixlogo img{display:block;width:92px;height:auto}.pixbadge b{color:#32BCAD;font-size:19px}.pixbadge small{color:#8fd6cf;display:block;font-size:14px;margin-top:2px}
.secure{display:flex;align-items:center;gap:8px;color:#9dffa9;font-size:15px;margin:14px 0 0}
.qr{background:#fff;padding:12px;width:256px;margin:15px auto}.copy{word-break:break-all;background:#070707;padding:10px;border-radius:10px;color:#aaa;font-size:16px}.good{color:#aaffb3;font-size:20px}.bad{color:#ff9292;font-size:18px}</style><style>body{background:#f7f5f0;color:#242424;font-family:Arial,sans-serif}.wrap{max-width:680px}.topbar{justify-content:flex-start;margin-bottom:18px}.logo img{height:58px;width:58px;background:#e6b93f;border:2px solid #242424;border-radius:50%;filter:none;padding:4px}.logo span{font-size:28px;color:#242424;letter-spacing:-.03em}.tablechip{text-align:left}.chip{background:#fffdf7;color:#242424;border:1px solid #d8d3ca;border-radius:6px;padding:7px 11px;font-size:14px}.hero h1{font-size:34px;color:#242424}.hero p{font-size:18px;color:#5f5a52}.step-dot{background:#ece8df;color:#777;border-radius:6px}.step-dot.active{background:#e6b93f;color:#242424;border:1px solid #242424}.card,.song{background:#fffdf7;color:#242424;border:1px solid #d8d3ca;border-radius:8px;box-shadow:0 3px 12px rgba(36,36,36,.07)}.song b{color:#c94a40}.song.selected{border-color:#c94a40}.chosen{background:#f1eee7;border:1px solid #d8d3ca;border-radius:8px}input,textarea{background:#fff;color:#242424;border:1px solid #bdb7ac;border-radius:6px}.btn{background:#c94a40;color:#fff;border:1px solid #9f3029;border-radius:6px;box-shadow:none}.btn.ghost{background:#fffdf7;color:#4169a1;border:1px solid #4169a1}.pixbadge{background:#f1eee7;border:1px solid #d8d3ca;border-radius:8px}.secure,.good{color:#237f75}.copy{background:#f1eee7;color:#5f5a52;border:1px solid #d8d3ca;border-radius:6px}.bad{color:#b33d35}</style></head><body><div class=wrap>
<style>
.wrap{padding-top:28px}.hero{margin:28px 0 20px}.hero h1{font-size:40px;letter-spacing:-.04em}.hero p{margin-top:10px}
.steps{margin:20px 0 12px}.step-dot{padding:12px 6px}.step-dot.active{font-size:15px}
#view1{background:#fffdf7;border:1px solid #d8d3ca;border-radius:10px;padding:20px;box-shadow:0 5px 18px rgba(36,36,36,.08)}
#view1 .field{margin-top:0}#view1 .field label{font-size:18px;font-weight:800;color:#242424;margin-bottom:9px}
