#toStep2{margin-top:18px}.topbar{margin-bottom:8px}
</style><div class=topbar><div class=logo><img src="<?=h($barLogo)?>" alt="<?=h($name)?>"><span><?=h($name)?></span></div></div><div class=tablechip><span class=chip><?=$label?></span></div>
<div class=hero><h1>Escolha. Pague. Tocou.</h1><p><?=$name?> · música <b id=base></b></p></div>
<?php if(!$ready):?><p class=bad>Cobranças sandbox ainda não configuradas pelo TocaRaul.</p><?php endif;?>
<div class=steps><div class="step-dot active" id=dot1>1 · Música</div><div class=step-dot id=dot2>2 · Seus dados</div><div class=step-dot id=dot3>3 · Pagamento</div></div>
<div id=view1 class="stepview on">
<div class=field><label>1. Busque e escolha sua música</label><input id=search placeholder="Digite o nome da música ou artista" autocomplete=off></div><p class=muted>Toque em uma música da lista para selecioná-la.</p>
<div id=catalog class=grid></div>
<button id=toStep2 class=btn disabled>Continuar</button>
</div>
<div id=view2 class=stepview>
<div class=card><h2>Seu pedido</h2><div id=chosenSummary class=chosen></div>
<div class=field><label>Nome</label><input id=visitor maxlength=80></div>
<div class=field><label>Dedicatória opcional (<?=$ded>0?'+ '.htmlspecialchars(number_format($ded/100,2,',','.'),ENT_QUOTES,'UTF-8'):'grátis'?>)</label><textarea id=message maxlength=180></textarea></div>
<div class=total><span>Total</span><span id=total></span></div>
<button id=pay class=btn <?=!$ready?'disabled':''?>>Gerar Pix</button>
<p id=error class=bad></p>
<button id=backTo1 type=button class="btn ghost">← Trocar música</button>
</div>
</div>
<div id=view3 class=stepview>
<div class=card>
<div class=pixbadge><div class=pixlogo><img src="/assets/pix_logo.svg" alt="Pix"></div><div><b>Pagamento via Pix</b><small>Sistema instantâneo do Banco Central do Brasil</small></div></div>
<div id=pixqr class=qr></div>
<div id=code class=copy></div>
<button id=copy class=btn>Copiar Pix</button>
<p class=secure>🔒 Ambiente seguro — o TocaRaul não vê nem guarda seus dados bancários, tudo passa direto pelo Pix.</p>
<p id=status>Aguardando confirmação...</p>
<button id=mockconfirm class="btn ghost">🧪 Já paguei (confirmar sandbox)</button>
</div>
</div>
</div>
<script src="/assets/qrcode.js"></script><script>
const token=<?=json_encode($token)?>,music=<?=$music?>,dedication=<?=$ded?>,ready=<?=$ready?'true':'false'?>;
let selected=null,requestId=null,searchTimer=null;const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);base.textContent=money(music);
function showStep(n){[1,2,3].forEach(i=>{document.getElementById('view'+i).classList.toggle('on',i===n);const d=document.getElementById('dot'+i);d.classList.toggle('active',i===n);d.classList.toggle('done',i<n)});window.scrollTo(0,0)}
function renderResults(list){catalog.innerHTML='';if(!list.length){catalog.innerHTML='<p style="color:#999">Nenhum resultado. Tente outro termo.</p>';return}list.forEach(s=>{let b=document.createElement('div');b.className='song'+(selected&&selected.id===s.id?' selected':'');b.setAttribute('role','button');b.setAttribute('tabindex','0');let img=document.createElement('img');img.src=s.thumbnail||'';img.alt='';let info=document.createElement('div');info.className='info';let strong=document.createElement('strong');strong.textContent=s.title;let artistSpan=document.createElement('span');artistSpan.textContent=s.artist;info.append(strong,artistSpan);let choose=document.createElement('span');choose.className='choose';choose.textContent=selected&&selected.id===s.id?'Selecionada':'Escolher';let price=document.createElement('b');price.textContent=money(music);b.append(img,info,choose,price);b.onclick=()=>{selected=s;renderResults(list);toStep2.disabled=false};catalog.appendChild(b)})}
function refresh(){total.textContent=money(music+(message.value.trim()?dedication:0));pay.disabled=!ready||!selected}
message.oninput=refresh;refresh();
try{visitor.value=localStorage.getItem('tocaraul_visitor')||''}catch(e){}
search.oninput=()=>{clearTimeout(searchTimer);const term=search.value.trim();if(term.length<2){catalog.innerHTML='';return}searchTimer=setTimeout(async()=>{catalog.innerHTML='<p style="color:#999">Buscando...</p>';try{let r=await fetch('/api/commerce/search?q='+encodeURIComponent(term)+'&qrToken='+encodeURIComponent(token));let d=await r.json();if(!r.ok){catalog.innerHTML='<p class=bad>'+(d.message||'Busca indisponível.')+'</p>';return}renderResults(d.results||[])}catch(e){catalog.innerHTML='<p class=bad>Busca indisponível no momento.</p>'}},400)};
function renderChosen(){chosenSummary.innerHTML='';if(!selected)return;let img=document.createElement('img');img.src=selected.thumbnail||'';img.alt='';let info=document.createElement('div');info.className='info';let strong=document.createElement('strong');strong.textContent=selected.title;let span=document.createElement('span');span.textContent=selected.artist;info.append(strong,span);chosenSummary.append(img,info)}
toStep2.onclick=()=>{if(!selected)return;renderChosen();refresh();showStep(2)};
backTo1.onclick=()=>{showStep(1)};
pay.onclick=async()=>{if(!selected)return;error.textContent='';pay.disabled=true;try{try{localStorage.setItem('tocaraul_visitor',visitor.value)}catch(e){}let r=await fetch('/api/commerce/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({qrToken:token,visitorName:visitor.value||'Cliente',providerId:selected.id,title:selected.title,artist:selected.artist,message:message.value})});let d=await r.json();if(!r.ok)throw Error(d.message||'Erro ao gerar Pix');requestId=d.requestId;code.textContent=d.pixCopyPaste;pixqr.innerHTML='';new QRCode(pixqr,{text:d.pixCopyPaste,width:232,height:232});showStep(3);poll()}catch(e){error.textContent=e.message;pay.disabled=!ready}};
async function poll(){try{let r=await fetch('/api/commerce/payment?requestId='+requestId,{cache:'no-store'}),d=await r.json();if(r.ok&&(d.paymentStatus==='APPROVED'||['QUEUED','PLAYING','PLAYED'].includes(d.requestStatus))){document.getElementById('status').innerHTML='<b class=good>Pagamento confirmado. Sua música entrou na fila.</b>';mockconfirm.style.display='none';return}}catch(e){}setTimeout(poll,4000)}copy.onclick=async()=>{await navigator.clipboard.writeText(code.textContent);copy.textContent='Pix copiado'};
mockconfirm.onclick=async()=>{mockconfirm.disabled=true;mockconfirm.textContent='Confirmando...';try{await fetch('/api/commerce/mock-confirm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId})})}catch(e){}mockconfirm.disabled=false;mockconfirm.textContent='🧪 Já paguei (confirmar sandbox)'};
</script></body></html>
